        return (app.get("employment") == "self_employed"
                and (app.get("requested_limit") or 0) > 6000)

    if outcome == "approved":
        if _referral():
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": int(credit_limit)}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    elif outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    else:
        # Safe default for unknown/missing outcome: manual review.
        return {"action": "queue_review", "limit": 0}

